insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 1, 'What are the four black-oil properties a study rests on?', '["Porosity, permeability, saturation and net pay, which are the four the volumetric estimate needs.", "Density, compressibility, thermal expansion and molecular weight, the four thermodynamic state properties.", "Solution gas ratio, formation volume factor, viscosity and bubble point pressure.", "Oil gravity, gas gravity, temperature and pressure, which are the four inputs every correlation takes."]'::jsonb, 2, 'A gas description adds the z factor, the gas formation volume factor and gas viscosity, and a water description adds Bw and water viscosity. Oil gravity, gas gravity, temperature and pressure are the INPUTS the correlations take rather than what they produce.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 2, 'A five percent error in the formation volume factor does what to a study?', '["It becomes a five percent error in every oil-in-place number the study quotes, and it does not announce itself.", "It cancels between the voidage and the oil in place, because the same factor appears in the numerator of one and the denominator of the other.", "It affects only the reservoir-condition volumes, since stock tank volumes are metered at surface and are independent of it.", "It averages out across a field, because different parts of the reservoir sit at different pressures and therefore different factors."]'::jsonb, 0, 'Bo is a unit conversion between two places, so an error in it scales everything proportionally and in the same direction. Systematic errors do not average away.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 3, 'Where can a number in a fluid description have come from?', '["A laboratory measured it or a correlation produced it; the other two are refinements of those two.", "A laboratory measured it, a correlation produced it, a tuned equation of state computed it, or somebody estimated it by an unchecked method.", "A laboratory measured it, a simulator computed it, or it was assumed, which are the three cases a report has to distinguish.", "It was measured directly at reservoir conditions or converted from a surface measurement, and the conversion between them is where the uncertainty lives."]'::jsonb, 1, 'All four are legitimate in the right place. Presenting the fourth as though it were the first is not, and that is the distinction the whole course is built on.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 4, 'Why is a number''s provenance hard to recover from a report?', '["Because reports are written by different people from the ones who produced the numbers, so the chain of custody is broken by convention.", "Because provenance is recorded in a metadata field most software does not populate, so it is lost at the first export.", "Because a correlation output carries more significant figures than a measurement, so precision is the only surviving clue.", "Because a table of Bo against pressure looks identical whether it came from a laboratory or a correlation."]'::jsonb, 3, 'By the time it reaches the third document that quotes it, nobody remembers. The simulation course made the same point about a deck: read on its own it is self-consistent, because it is one file.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 5, 'Which six tiers does the engine''s provenance ladder use?', '["Measured, armed, oracle gated, lab tuned, published method and screening.", "Measured, correlated, computed, estimated, assumed and unknown, which are the six a report has to distinguish.", "Certain, likely, plausible, screening, speculative and placeholder, ranked by confidence in the value.", "Laboratory, field, literature, correlation, simulation and default, ranked by where the number originated."]'::jsonb, 0, 'Measured is the strongest and the rarest. Armed means the engine reproduces a published study within a stated tolerance; oracle gated means an independent implementation agrees on the arithmetic.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 6, 'What does the tier of a quantity tell you?', '["How large the error in the value is likely to be, on a scale the engine calibrated against its own gate suite.", "Whether the number may be used in a booking, which is what the ladder was designed to decide.", "What kind of confidence you have, not how much, so reading it means asking what the tier is confidence about.", "How recently the number was produced, since a lower tier generally means an older method."]'::jsonb, 2, 'An oracle gated flash is arithmetically exact and can still describe the wrong fluid. A published method correlation has no independent check and may be perfectly adequate for a screening study.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 7, 'Which tier does this course refuse to grade, and why?', '["Published method, because a method with no independent check of its result cannot support a graded field.", "Screening, because certifying that a learner can produce a number implies the number is worth producing, and a screening estimate may be out by a factor of two.", "Lab tuned, because a tuned value depends on which measurements it was tuned to and is therefore not reproducible.", "Measured, because the course has no laboratory and cannot ask a learner to reproduce an experiment."]'::jsonb, 1, 'The Expert tier has a whole module on screening quantities and grades none of it, exactly as the simulation course taught results literacy and graded none of that. Teaching a number and certifying it are different acts.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 8, 'Why does the engine attach a tier to the value it returns?', '["Because the tier is required by the grading chassis, which cannot construct a capstone field without one.", "Because different tiers use different numerical precision, so the tier tells the caller how many digits to keep.", "Because regulatory reporting requires a provenance statement against every quantity in a reserves submission.", "Because a library that returns a number and nothing else forces every caller to rediscover its limits, and most callers do not."]'::jsonb, 3, 'The alternative most software chooses is to document the limits somewhere else, which works until the documentation and the code drift. Attaching the tier to the returned value keeps them together.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 9, 'What does the black-oil model replace a real reservoir fluid with?', '["Two pseudo-components, a stock tank oil and a surface gas, with the behaviour carried by how much gas is dissolved and how much the oil swells.", "Eleven components, the nine identifiable light ones plus a heavy fraction and an inert fraction.", "One component, since a black oil is by definition a single liquid phase over the pressure range of interest.", "Three components, an oil, a gas and a water, each with its own formation volume factor and viscosity."]'::jsonb, 0, 'It works because for most oil reservoirs the composition does not change much, so the gas coming out of solution is roughly the same gas each time. Water is present and is not one of the two pseudo-components the model is named for.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 10, 'Where does the black-oil description stop working?', '["Heavy oils below 20 API, where the correlations behind it were never properly fitted and the viscosity is dominated by molecular structure.", "Undersaturated reservoirs, where there is no free gas phase and the two-component description has nothing to partition.", "Volatile oils and condensates near the critical point, gas injection, and anything where the composition itself is the answer.", "High-temperature reservoirs above 300 F, where the correlations leave their published range and extrapolate."]'::jsonb, 2, 'Three of the four failure cases are about composition changing, which is exactly what the black-oil model assumes does not happen. An undersaturated reservoir is where the description works BEST.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 11, 'Why is Ekene the right fluid to learn the correlations on?', '["Because it is a real measured fluid, so the correlations can be checked against a laboratory for the first time.", "Because its properties were designed rather than measured, so every correlation output has a known value to be held against.", "Because it sits unusually close to the population Standing''s correlation was fitted to, so the agreement between them is exceptionally good.", "Because it is the only fluid in the engine''s fixtures with a full compositional analysis behind it."]'::jsonb, 1, 'A designed fluid is one whose true answer you know, which is what makes it a teaching fluid. It has no laboratory PVT at all, and its composition is never given.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 12, 'What is Good Oil Co. Well No. 4?', '["A synthetic benchmark fluid published by the SPE for comparing compositional simulators.", "The engine''s own synthetic fixture fluid, designed specifically to exercise the near-critical branch of the phase envelope tracer.", "A field in the Ekene series, added for this course so the compositional tiers have a subject.", "A real published reservoir fluid study, Core Laboratories RFL 88001, reproduced in McCain and in Whitson and Brule."]'::jsonb, 3, 'It is one of the most reproduced PVT studies in the literature because it is complete and unremarkable, which is exactly what a teaching example needs.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 13, 'Ekene bubbles at 2000 psia and starts at 3200. Good Oil''s bubble point and reservoir pressure are both 2634.65. What does that difference mean?', '["Ekene is undersaturated by 1200 psia at discovery, while Good Oil''s sample was AT its bubble point at reservoir conditions.", "Ekene''s reservoir is deeper, so its higher initial pressure reflects the extra overburden rather than anything about the fluid.", "Good Oil''s study was run at a lower temperature, which lowered its bubble point until it coincided with the reservoir pressure.", "Ekene''s numbers are designed and Good Oil''s are measured, so the two pressures cannot meaningfully be compared at all."]'::jsonb, 0, 'A reservoir whose initial pressure equals its bubble point is called saturated at discovery, and it is a special case rather than the norm. Confusing an initial pressure with a bubble point is the commonest arithmetic error in this material.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 14, 'Which is the harder question about a fluid description?', '["What each number is, because the definitions involve reference conditions that vary between reports.", "How to compute each number, because the correlations are numerous and each has its own conventions.", "Where each number came from, because the arithmetic can be looked up and the provenance usually cannot.", "Which correlation is best, because the answer depends on the fluid and the published guidance conflicts."]'::jsonb, 2, 'An engineer who cannot say which of the four possible origins applies to their formation volume factor has not finished reading their own model. The arithmetic is the easy half.'),
  ('fluid', 'beginner', 'module', 'm01-where-a-number-comes-from', 15, 'What is the misconception about PVT being an input?', '["That it makes it fixed, when in practice a fluid description is revised several times over a field''s life.", "That it makes it somebody else''s problem, when it is an input to everything and is produced by a chain of usually undocumented decisions.", "That it makes it uncertain, when a laboratory measurement is among the better constrained numbers in a study.", "That it makes it independent of the reservoir model, when the two are solved together in a modern simulator."]'::jsonb, 1, 'A five percent error in Bo is a five percent error in every volume the study books, and it arrives without announcement from a chain nobody wrote down.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 1, 'What is a bubble point pressure?', '["The pressure at which the last bubble of gas redissolves as an oil is compressed at constant temperature, which is the same boundary from the other side.", "The pressure at which the first bubble of gas appears as an oil is expanded at constant temperature.", "The pressure at which the oil and gas phases have equal density, which is where the two become indistinguishable in the cell.", "The pressure at which a well begins to produce free gas at surface, measured from the producing gas-oil ratio."]'::jsonb, 1, 'It is a property of the fluid at a temperature and nothing else. A well producing free gas at surface is a different event: free gas does not flow until it exceeds its critical saturation, so the two do not coincide.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 2, 'What happens to the reservoir fluid as pressure falls below the bubble point?', '["The oil expands as dissolved gas comes out of solution, and the expansion is what drives production below the bubble point.", "The oil thins as the heavier components condense out, and the lighter remaining liquid flows more easily to the wells.", "Nothing changes in the oil itself; only the free gas saturation rises, which is why the crossing is hard to detect.", "The oil shrinks, the oil thickens, and a far more mobile second phase appears."]'::jsonb, 3, 'Bo falls because the swelling gas has left, viscosity rises because the thinning gas has left, and gas viscosity is two orders of magnitude below oil viscosity so gas flows preferentially.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 3, 'Ekene starts at 3200 psia with a bubble point of 2000 psia. What follows?', '["It is undersaturated by 1200 psia at discovery, so the depletion over that interval is driven by oil expansion alone.", "It is saturated at discovery, so free gas is present from the first day of production onward.", "It has 1200 psia of gas cap support above the oil column, which supplies the drive over that interval.", "It will cross its bubble point within the first year of production, since 1200 psia is a fairly small interval for a producing field."]'::jsonb, 0, 'Oil expansion is a weak drive because oil compressibility is small, so pressure falls fast for the oil produced. Whether the crossing happens quickly depends on the offtake rather than on the size of the interval.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 4, 'Standing''s correlation was fitted to what?', '["Over 6000 measurements from a worldwide data set, split into two coefficient sets at 30 API gravity.", "A set of North Sea oils, which is the reason it carries the engine''s screening label rather than the published method one.", "105 experimentally determined bubble points from 22 crude oil and natural gas mixtures, all from California.", "The Standing-Katz chart, which was itself assembled from measurements on natural gases in the 1940s."]'::jsonb, 2, 'That is not a criticism, it is the definition, and it is why three correlations disagree. The second describes Vasquez-Beggs, the third Glaso, and the fourth is what the z factor correlations fit.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 5, 'Standing gives Ekene a bubble point of 1912.1923059028293 psia against a designed 2000. What is that?', '["About 4.4 percent low, which is an entirely ordinary distance for a published correlation to sit from any particular oil.", "About 4.4 percent low, which is outside the correlation''s stated accuracy and indicates an input error.", "About 8.8 percent low, since the difference of 88 psia should be taken against the correlated value.", "Exactly the difference the designed fluid was chosen to have, so that the course would have something to measure."]'::jsonb, 0, 'The designed 2000 is a decision and the correlated 1912 is what a fit to Californian oils says. Neither is a measurement of Ekene, because nobody has measured Ekene.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 6, 'Read Standing the other way, fixing Ekene''s bubble point at 2000 psia. What does it return?', '["The designed 400 scf/stb exactly, since the correlation is being given the bubble point the fluid was designed around.", "421.93922752270595 scf/stb against the designed 400, which is the same disagreement seen from the other direction.", "1912.19 psia again, since a correlation run in reverse must return the value it was given as an input.", "A different bubble point, since the correlation is not exactly invertible and each direction has its own fit."]'::jsonb, 1, 'Both statements are one disagreement expressed twice. All three correlations invert exactly or by solving for the physical root, and the engine gates the round trip.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 7, 'Why does the bubble point spread across three correlations matter more than any single value?', '["Because the average of the three is closer to the truth than any one of them, which is what makes the spread useful.", "Because the widest correlation defines the uncertainty band, and the others fall inside it by construction.", "Because a single number tells you nothing about its own reliability, and three independent fits measure how well a correlation can know this fluid.", "Because a spread above a few percent means one of the three has been implemented wrongly and should be found."]'::jsonb, 2, 'Do not average them: the average of three fits to three different populations is a fit to nothing, with no error bar and no provenance. The disagreement is the information.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 8, 'One of the three correlations carries the engine''s screening label. Which, and what does that mean?', '["Vasquez-Beggs, and it means the correlation splits its coefficients at 30 API so it is discontinuous.", "Standing, and it means the correlation is old enough that its data set is no longer considered representative.", "All three, since every correlation is a fit to somebody else''s samples and none has an independent check.", "Glaso, and it means the value is usable for ranking and not for booking."]'::jsonb, 3, 'An audit of the engine''s implementations flagged Glaso''s solution gas branch as suspect. It remains selectable and it comes with a warning, which is the honest option: removing it would mean a user who asks for Glaso quietly gets something else.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 9, 'What must a Pb and an Rs correlation satisfy together?', '["A round trip: put Rs in, get Pb out, put that Pb back in, and the original Rs must return.", "Continuity at the bubble point, so that the saturated and undersaturated branches meet without a step.", "Monotonicity in pressure, so that a root-finder solving either direction cannot land on the wrong solution.", "Agreement with a second correlation to within the published scatter of the two data sets."]'::jsonb, 0, 'A single mistyped exponent breaks the round trip while leaving each direction looking plausible on its own. The engine gates it for all three correlations and it costs two lines to check.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 10, 'Why do all three Rs correlations take a pressure AND a bubble point?', '["Because the correlations were fitted on data that reported both, and dropping either would leave the fit under-determined.", "Because an undersaturated oil has released no gas, so Rs above the bubble point is constant at its bubble point value.", "Because the bubble point is needed to select which coefficient set applies, in the same way Vasquez-Beggs splits at 30 API.", "Because the pressure sets the value and the bubble point sets the validity range the warning function checks against."]'::jsonb, 1, 'A correlation that kept increasing Rs with pressure above the bubble point would be describing an oil that dissolves gas which is not there. All three clamp at the bubble point.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 11, 'Glaso''s bubble point form has to be inverted numerically. Why?', '["Because it is fitted to a spline rather than to a closed-form expression, so no algebraic inverse exists at all.", "Because its coefficients change discontinuously with oil gravity, so each branch has to be inverted separately.", "Because it runs through a quadratic in the logarithm, so inverting it means solving that quadratic and picking the physical root.", "Because it was published only in the pressure direction, and the solution gas direction was added later by other authors."]'::jsonb, 2, 'The engine takes the lower root and guards the case where the discriminant goes negative, which should not happen on a physical fluid. A correlation published in one direction may need real numerical work to run in the other.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 12, 'Which way does a bubble point move?', '["Up with more dissolved gas, down with lighter oil, up with higher temperature, since lighter oils hold gas more readily.", "Up with more dissolved gas and independent of oil gravity, which enters only the formation volume factor.", "Down with more dissolved gas, since more gas in solution means the oil is further from releasing any of it.", "Up with more dissolved gas, up with lighter oil, up with higher temperature."]'::jsonb, 3, 'The direction is the sanity check on any correlation output. A bubble point that goes down when you add gas has been computed wrongly.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 13, 'Why does the Ekene deck carry a bubble point of 2000 psia rather than the correlated 1912?', '["Because consistency across the study beats agreement with a correlation: the tank model, the flood ledger and the deck were all built on 2000.", "Because the correlated value is less accurate, since Standing was fitted to Californian oils and Ekene is not one.", "Because a deck must carry a round number for the equilibration to converge, and 1912.19 would be rejected by the validator.", "Because the correlated value falls outside Standing''s published validity range at this oil gravity and temperature."]'::jsonb, 0, 'Change it in one place and every earlier calculation becomes slightly wrong for reasons nobody downstream can see. The simulation course stated this as a rule: a deck''s fluid must be the fluid the rest of the study was matched against.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 14, 'What would you do on a real field where the bubble point mattered?', '["Run all three correlations and take the median, which is more robust than any single fit to an unfamiliar oil.", "Measure it, because a single constant composition expansion gives it and it is the most consequential number to get wrong.", "Adjust the correlated value toward the field''s observed producing gas-oil ratio history until the two agree.", "Use whichever correlation''s fitted population is geographically closest to the field, on the grounds that it is the best available proxy."]'::jsonb, 1, 'Until you have that measurement you are choosing between correlations, and the honest report says so and gives the spread. Adjusting a value toward a preference is the failure mode this course keeps naming.'),
  ('fluid', 'beginner', 'module', 'm02-the-bubble-point', 15, 'Is four percent on a bubble point a small error?', '["It is small, since four percent is well inside the scatter of any published correlation and inside measurement error.", "It is large, since a bubble point is the best-determined quantity in a PVT report and should agree to under one percent.", "It is small as a pressure and not small in its consequences, because the bubble point decides which regime the reservoir is in.", "It cannot be judged without knowing the reservoir temperature, since the error scales with the absolute temperature the value was computed at."]'::jsonb, 2, 'A field forecast to stay 50 psia above its bubble point for ten years is a completely different forecast from one that crosses it in year three. Whether four percent matters depends on how close to the crossing you are.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 1, 'What is the solution gas ratio a ratio of?', '["A reservoir gas volume over a reservoir oil volume, both measured at the pressure and temperature of interest.", "A surface gas volume over a reservoir oil volume, which is the reason the formation volume factor is needed to convert between them.", "Two SURFACE volumes: gas at standard conditions over oil in a stock tank, describing a fluid that is in the reservoir.", "A mass of dissolved gas over a mass of oil, converted to volumes at the end using the two standard densities."]'::jsonb, 2, 'Both volumes are countable at surface with ordinary equipment. A reservoir-condition definition would need pressure and temperature quoted with every number and would not correspond to anything anybody sells.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 2, 'What shape does the Rs curve have from atmospheric pressure to well above the bubble point?', '["Zero at the tank, rising steeply at first, reaching Rsb at the bubble point, and then flat above it all the way up.", "Flat at zero right up to the bubble point and then rising steeply, because gas only dissolves once the oil is undersaturated.", "Rising steadily across the whole range without a break, since more pressure always dissolves more gas.", "Peaking at the bubble point and falling on both sides, which is the shape the formation volume factor also has."]'::jsonb, 0, 'Above the bubble point the oil holds all its gas and releasing pressure does not change that. The peak-and-fall shape belongs to Bo rather than to Rs.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 3, 'What distinguishes the solution gas ratio from the producing gas-oil ratio?', '["The first is measured at the separator and the second at the wellhead, so they differ by whatever the tubing releases.", "The first is a fluid property and the second is a well measurement; they are equal above the bubble point and diverge below it.", "The first includes only the gas dissolved in the oil and the second includes gas cap gas as well, so they differ by the cap''s contribution.", "They are the same quantity under different names, one used in reservoir engineering and one in production operations."]'::jsonb, 1, 'Below the bubble point free gas flows preferentially, so the producing ratio climbs above Rs and keeps climbing. The gap between them is the diagnostic the material balance course used.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 4, 'Why is the formation volume factor always above one for a live oil?', '["Because reservoir temperature is above 60 F, and thermal expansion alone accounts for the whole excess.", "Because a reservoir barrel is defined at a smaller reference pressure than a stock tank barrel, so the ratio exceeds one.", "Because the correlations were fitted with a lower bound of one, so a value below one is outside their range.", "Because dissolved gas swells the oil, and that swelling beats the compression that pressure applies to it."]'::jsonb, 3, 'Three effects act: swelling and thermal expansion push it up, compression pushes it back, and swelling wins comfortably. A dead oil with no dissolved gas would sit just above one from temperature alone.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 5, 'What shape does Bo have across the pressure range?', '["It rises with pressure up to the bubble point, peaks there, and falls above it.", "It falls with pressure across the whole range, because the oil is being compressed throughout.", "It rises with pressure across the whole range, because more gas stays in solution at higher pressure.", "It is flat below the bubble point and falls above it, since Rs is what varies below and compression is all that acts above."]'::jsonb, 0, 'Below the bubble point more gas stays in solution as pressure rises and swells the oil; above it no more gas is available and only compression acts. A curve rising all the way to the top has lost its bubble point.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 6, 'Standing gives Ekene a Bo of 1.2407824121407645 rb/stb at the designed 400 scf/stb. What does that gap do?', '["About 3.4 percent, which cancels against the voidage calculation because Bo appears in both.", "About 34 percent, since the designed value of 1.2 should be compared against the correlated value of 1.24 as a ratio.", "About 3.4 percent, which becomes a 3.4 percent error in every volume the field books, straight through.", "Nothing measurable, since 3.4 percent is well inside the uncertainty of the porosity and saturation inputs."]'::jsonb, 2, 'On Ekene''s booked 12.139 million barrels that is roughly 400 thousand barrels. It is also sixty times the residual the simulation course worked to close on its structure.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 7, 'Feed Standing the CORRELATED 421.94 scf/stb instead of the designed 400. What happens to Bo?', '["It falls, because the higher solution gas ratio implies a lighter oil which occupies less reservoir space.", "It rises to 1.2516120850485737 rb/stb, because more dissolved gas swells the oil more.", "It stays the same, because Bo depends on the bubble point rather than on the solution gas ratio at it.", "It becomes undefined, because the correlated solution gas exceeds what the designed bubble point can hold."]'::jsonb, 1, 'Two correlated numbers, both defensible, both different from the design, and the difference between the two correlated ones is entirely down to which solution gas ratio was fed in.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 8, 'What are the two regimes a black-oil correlation has to know it is in?', '["Single phase and two phase, which is the same distinction expressed in terms of what is present in the pore space.", "Depletion and injection, since the fluid description differs between primary and secondary recovery.", "Reservoir and surface, since a correlation applied at separator conditions uses a different coefficient set.", "Undersaturated above the bubble point and saturated at or below it."]'::jsonb, 3, 'Both curves are continuous at the bubble point but neither is smooth: the slope changes sign for Bo and for viscosity, and that kink is real.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 9, 'How does the engine handle Bo above the bubble point?', '["The correlations return the SATURATED value, and the undersaturated branch is applied on top by the caller through a compressibility.", "The correlations take the pressure and the bubble point and clamp internally, exactly as the Rs correlations do.", "The correlations extrapolate their fitted form above the bubble point, which is why the validity warning fires there.", "The engine interpolates between the bubble point value and unity at the initial pressure, which is the standard convention."]'::jsonb, 0, 'That split matters. Asking a Bo correlation for the value at 3200 psia on an oil that bubbles at 2000, and expecting it to handle the undersaturation itself, gets you the bubble point value.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 10, 'Ekene bubbles at 2000 psia and starts at 3200. With a compressibility of 1.5e-5 per psi, what does Bo do over that interval?', '["It rises by about two percent, because higher pressure keeps more gas in solution and swells the oil further.", "It falls by about twenty percent, since the compressibility applies to the whole 1200 psia rather than to the exponent.", "It falls by about two percent from the bubble point up to initial pressure, because the oil is being compressed.", "It is unchanged, since above the bubble point no gas leaves solution and Bo is set entirely by the solution gas ratio."]'::jsonb, 2, 'Small, systematic, and it goes the right way: squeezing an oil makes it smaller. That is also why the waterflood course could treat the factors as frozen constants over the range the field actually saw.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 11, 'Where does a PVT table most often lose its bubble point?', '["In the extrapolation above the highest tabulated pressure, where the undersaturated branch runs off the end.", "In the interpolation, when the table carries no row AT the bubble point and the peak simply gets cut across.", "In the conversion to Mscf/stb, where the factor of a thousand is applied to Rs and not to the pressure column.", "In the units, where a table in rb/stb is read as a table in reservoir barrels per reservoir barrel."]'::jsonb, 1, 'The simulation deck''s PVTO record makes the distinction explicit by separating saturated nodes from undersaturated branches, which is why that format resists this particular error.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 12, 'What does the designed Ekene fluid buy the series?', '["Traceability: because the fluid never changed, a factor quoted in one course is the same number as in the next, so a discrepancy means a real error.", "Accuracy, since a designed set can be made internally consistent in a way a measured set never is.", "Simplicity, since designed round numbers are easier to carry through hand calculations across five courses.", "Independence, since a designed fluid owes nothing to any published correlation and so cannot inherit its errors."]'::jsonb, 0, 'On a real field that property is usually absent: fluid descriptions get revised and the revisions rarely propagate to every calculation that used the old one.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 13, 'Substituting the correlated Bo for the designed one changes Ekene''s oil in place by how much and in which direction?', '["Up by about 3.3 percent, because a larger factor means each reservoir barrel yields more stock tank oil.", "Down by about 3.3 percent, because a larger factor means more reservoir volume was produced per barrel booked.", "It cannot be determined without the reservoir volume, since the two enter the calculation multiplicatively.", "Down by about 3.3 percent, because oil in place divides by Bo."]'::jsonb, 3, 'A larger Bo means each stock tank barrel occupied more reservoir space, so a fixed reservoir volume holds fewer of them. That is roughly 400 thousand barrels on this field.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 14, 'What does a 3.4 percent larger Bo do to a voidage replacement ratio?', '["It raises the ratio by about 3.4 percent, because more reservoir volume was produced for the same injection.", "It leaves the ratio unchanged, because both the injected and the produced voidage scale with the same factor.", "It lowers the ratio by about the same 3.4 percent, because produced voidage multiplies by Bo and sits in the denominator.", "It changes the ratio unpredictably, because Bo enters the produced side and Bw enters the injected side."]'::jsonb, 2, 'A field managed at a ratio of 1.03 would be reported at about 1.00, which is the difference between replacing voidage and not. The whole surveillance conclusion shifts on a property nobody measured.'),
  ('fluid', 'beginner', 'module', 'm03-solution-gas-and-volume', 15, 'Why do small percentage errors in PVT not wash out?', '["Because they are usually larger than reported, since correlation scatter is quoted as a standard deviation.", "Because they are systematic rather than random, so they compound in the same direction through every calculation that uses them.", "Because they enter the calculation multiplicatively, and multiplicative errors always grow rather than cancel.", "Because the properties are correlated with each other, so an error in one implies a matching error in the others."]'::jsonb, 1, 'A Bo that is three percent high is three percent high in the oil in place, the voidage, the recovery factor''s denominator and the forecast. Nothing averages it away.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 1, 'What is dead oil?', '["Oil with no dissolved gas, at stock tank conditions of 60 F and atmospheric pressure, which is what a tank sample is.", "Oil with no dissolved gas, at reservoir temperature.", "Oil from a reservoir that has been depleted below its abandonment pressure and no longer flows to the wells.", "Oil whose light components have been lost during sampling, so that its measured properties understate the live fluid."]'::jsonb, 1, 'Nobody produces dead oil from a reservoir. It is an intermediate quantity in a correlation chain, and measuring a tank sample at ambient temperature instead gives a number that is far too high.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 2, 'Beal''s dead oil correlation raises API gravity to the power 4.53 in a denominator. What follows?', '["Viscosity falls extremely steeply with gravity, so a 20 API oil and a 40 API oil differ by more than an order of magnitude.", "Viscosity is largely insensitive to oil gravity, since such a large exponent sitting in a denominator compresses the range of outcomes.", "The correlation cannot be used below 20 API, because the denominator grows without bound at low gravity.", "Gravity has to be known to four figures, because the exponent amplifies rounding in the input."]'::jsonb, 0, 'It also means viscosity correlations are far more sensitive to a gravity error than volume correlations are, which is worth knowing when the gravity itself came from a correlation.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 3, 'Beal gives Ekene a dead oil viscosity of 2.3437444714709295 cp against a designed live oil viscosity of 1.8 cp. Is that the right way round?', '["No: a dead oil should be thinner, since it has lost the heavy components that make a live oil viscous.", "Yes, but only because the two are quoted at different temperatures, and at a common temperature they would agree.", "It cannot be judged, since a dead oil viscosity and a live oil viscosity are not comparable quantities.", "Yes: the dead oil is thicker precisely because the dissolved gas that thins it has not been put back in yet."]'::jsonb, 3, 'Dissolved gas thins oil substantially, and putting it back in is the next step of the chain. The two are directly comparable and the ordering is the check.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 4, 'What does Beggs and Robinson''s live oil correlation take as its inputs?', '["The oil gravity, the temperature and the solution gas ratio, which are the three the chain has available at that point.", "The dead oil viscosity and the pressure, since it is the pressure that decides how much gas is dissolved.", "The dead oil viscosity and the solution gas ratio.", "The bubble point, the solution gas ratio and the oil gravity, from which it computes the dead oil viscosity internally."]'::jsonb, 2, 'The dead oil viscosity enters raised to a power less than one, which compresses the range: a very thick dead oil is thinned proportionally more than a thin one.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 5, 'Beggs and Robinson take Ekene''s dead oil to 0.7559673199800581 cp at 400 scf/stb. What is the size of that effect?', '["The oil has been thinned to less than a third of its dead value, which is why a viscosity quoted without saying whether it is live or dead means very little.", "The oil has been thinned by about a third, which is a modest correction compared with what pressure does above the bubble point.", "The oil has been thickened, since dissolved gas increases the density of the liquid and therefore its resistance to flow.", "The effect cannot be separated from the temperature dependence, since both enter through the same exponential."]'::jsonb, 0, 'Light molecules going into solution get between the heavy ones and make the liquid flow more easily. Pressure above the bubble point moves it by a few percent, not by a factor of three.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 6, 'The same chain gives 0.7559673199800581 cp at 400 scf/stb and 0.7341185203712621 cp at 421.94 scf/stb. Which is correct?', '["The second, because 421.94 is what Standing returns at the designed bubble point and is therefore the consistent input.", "Both, and quoting either as the correlated viscosity without saying which solution gas ratio went in is what is wrong.", "The first, because the designed 400 scf/stb is the value the rest of the series carries and consistency governs.", "Neither, because mixing a designed solution gas ratio with a correlated viscosity chain is not a defensible combination."]'::jsonb, 1, 'Same correlations, same fluid, different answer, because the input differed. The number is not the answer; the number plus the chain that produced it is the answer.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 7, 'What does pressure do to oil viscosity above the bubble point?', '["It thins the oil, because the higher pressure keeps more gas dissolved and dissolved gas is what thins it.", "It leaves the viscosity unchanged, since a liquid is nearly incompressible and viscosity depends on density.", "It thickens the oil, modestly and roughly linearly, because compression is the only mechanism left once no gas remains to release.", "It thickens the oil sharply, by roughly the same factor that dissolved gas thinned it, so the two nearly cancel."]'::jsonb, 2, 'Ekene''s live oil goes from 0.7559673199800581 cp at the bubble point to 0.8035947954460412 cp at 2600 psia, about six percent for 600 psia of compression. Small compared with what the gas did, and in the opposite direction.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 8, 'What shape does the oil viscosity curve have across the pressure range?', '["A maximum at the bubble point, falling on both sides, which mirrors the shape of the formation volume factor.", "A monotonic fall with pressure across the whole range, since expansion and gas release both thin the oil.", "A step at the bubble point, since the mechanism changes discontinuously from gas release to compression.", "A minimum at the bubble point, rising on both sides."]'::jsonb, 3, 'Below the bubble point viscosity rises as pressure falls because gas is leaving; above it viscosity rises as pressure rises because the oil is being compressed. The two mechanisms compete and change places at the bubble point.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 9, 'A viscosity table has no minimum at the bubble point. What are the two likely causes?', '["The undersaturated branch was never applied, or the bubble point row is missing so the interpolation cuts across the minimum.", "The correlation was run outside its validity range, or the dead oil viscosity was measured at ambient temperature.", "The solution gas ratio was clamped at the wrong pressure, or the table was built in the wrong unit for viscosity.", "The oil is undersaturated over the whole of the tabulated pressure range, or the fluid is a gas condensate rather than a black oil."]'::jsonb, 0, 'Both are visible on a plot in a second and invisible in a column of numbers, which is a good reason to plot a PVT table before using it.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 10, 'Why does the small undersaturated viscosity effect still matter?', '["Because it compounds over the field''s life, and a six percent error each year becomes large after a decade.", "Because a reservoir spends its early life undersaturated, and productivity index scales inversely with viscosity.", "Because it is the only part of the chain that a laboratory can measure directly, so it anchors the other two.", "Because it enters the mobility ratio, which the waterflood course showed is the most sensitive quantity in a flood design."]'::jsonb, 1, 'Ekene sat 1200 psia above its bubble point at discovery, which is when the wells were drilled and the productivity measured. Using the bubble point value across that interval overstates what the wells will do.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 11, 'What is the structure of the oil viscosity calculation?', '["One correlation with three branches, selected by whether the fluid is dead, saturated or undersaturated.", "Two correlations, a dead oil and a live oil, with the undersaturated case handled by the same live oil form.", "Three correlations in series, each consuming the previous one''s output.", "A single fit to laboratory viscosity data, with the three stages being an exposition rather than a computation."]'::jsonb, 2, 'Beal for the dead oil, Beggs and Robinson for the effect of dissolved gas, Vasquez and Beggs for the effect of pressure above the bubble point. Composition of published methods is normal practice.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 12, 'What does composing three correlations do to the uncertainty?', '["The errors partly cancel, because each stage was fitted to a different data set and the biases are independent.", "The uncertainty is set by the last stage, since that is where the final number is produced and rounded.", "The uncertainty becomes unquantifiable, because no published scatter exists for a composed chain.", "The errors compound rather than average out, and the first stage of the chain usually contributes the most."]'::jsonb, 3, 'Beal''s dead oil scatter is the widest of the three, so an undersaturated viscosity that looks precise is inheriting a dead oil viscosity that was never precise.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 13, 'Why is the correlated viscosity of the Ekene oil not well defined until the chain is named?', '["Because Beal is not the only dead oil correlation the engine carries, and a different first stage moves every number after it.", "Because the temperature at which the chain is evaluated is not stated, and viscosity depends strongly on it.", "Because the correlation set differs between the black-oil path and the compositional path, which use different models entirely.", "Because the chain has to be run at a pressure, and no pressure is implied by the phrase on its own."]'::jsonb, 0, 'Beggs and Robinson published their own dead oil correlation, which gives a different answer for the same gravity and temperature, and Beal-Cook-Spillman is a third the engine labels screening.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 14, 'How should a correlated viscosity be reported?', '["To two significant figures, since that is all a correlated transport property can support and the digits imply otherwise.", "With the chain and the inputs, so somebody else can reproduce it: the value, the three correlations, the solution gas ratio, the pressure and the temperature.", "With its validity warnings attached, which is sufficient because the warnings name the correlations that produced it.", "As a range across the available correlations, since a single value from one chain implies a precision it does not have."]'::jsonb, 1, 'The bare number is not reproducible. Rounding and quoting a range are both good practice and neither says which chain ran.'),
  ('fluid', 'beginner', 'module', 'm04-viscosity', 15, 'The designed Ekene viscosity is 1.8 cp and the correlated chain gives 0.7559673199800581 cp. What is unusual about that gap compared with the volume properties?', '["It is smaller than the volume gaps, because viscosity correlations were fitted to far larger data sets.", "It is the same size as the volume gaps once expressed as a percentage of the designed value rather than a ratio.", "It is a factor of 2.4, where the volume properties agreed to a few percent, because viscosity depends on molecular detail that gravity and temperature do not capture.", "It runs in the opposite direction, since the correlated volume properties came out high and the viscosity came out high too."]'::jsonb, 2, 'That asymmetry is typical, and it is the argument for measuring viscosity if you can measure only one thing about a fluid.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 1, 'What is the z factor?', '["The compressibility of the gas, defined as the fractional volume change per unit pressure change at constant temperature.", "The ratio of the gas density at reservoir conditions to that same gas''s density at standard conditions, which is why it exceeds one.", "Exactly the factor that makes the ideal gas law come out true, so it is the ratio of the real molar volume to the ideal one.", "A correction for the gas gravity, since a heavier gas departs further from ideality at the same pressure and temperature."]'::jsonb, 2, 'It is a fudge factor with a precise meaning. Compressibility is a different quantity and the density ratio is a different quantity again.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 2, 'What shape does a z curve have as pressure rises at fixed temperature?', '["It starts near one, dips below one as attraction dominates, then rises back through one as molecular volume dominates.", "It falls monotonically from one, since real gases are always more compressible than ideal ones at reservoir conditions.", "It rises monotonically from one, since the molecules'' own volume always reduces the space available to them.", "It stays near one until the critical pressure and then falls sharply, which is what makes the critical region difficult."]'::jsonb, 0, 'The dip and recovery is the shape of every z curve. A z of 1.4 at 500 psia is wrong, and a z of 0.4 anywhere on an ordinary natural gas is wrong.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 3, 'Why does one z chart work for all natural gases?', '["Because natural gases are all mostly methane, so their behaviour is dominated by one component in every case.", "The principle of corresponding states: two gases at the same reduced pressure and temperature behave alike.", "Because the chart is drawn for a reference gas and a gravity correction is applied on top of it afterward.", "Because the departures from ideality are small enough that a single average curve is adequate for engineering work."]'::jsonb, 1, 'The pseudo-critical properties are a mixture average, and for a natural gas of known gravity the engine uses Sutton (1985) to get them.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 4, 'Ekene''s gas gravity is 0.75. What are its Sutton pseudo-criticals?', '["667.8 psia and 343.0 degrees Rankine, which are methane''s own critical properties and a reasonable proxy.", "756.8 psia and 169.2 degrees Rankine, which are the leading constants of the two Sutton expressions.", "They cannot be computed from gravity alone; a compositional analysis is required to obtain a mixture average.", "656.525 psia and 389.7 degrees Rankine."]'::jsonb, 3, 'Quoting 756.8 and 169.2 gives the constant terms of the two Sutton expressions rather than evaluating them. The whole point of a gravity correlation is that it does not need a composition.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 5, 'At 3200 psia and 180 F on a 0.75 gas, what is the reduced state?', '["A reduced pressure of 4.874147976086212 and a reduced temperature of 1.6414421349756225.", "A reduced pressure of 4.874147976086212 and a reduced temperature of 0.4618, taking temperature in Fahrenheit.", "A reduced pressure of 4.234 and a reduced temperature of 1.6414421349756225, using 460 rather than 459.67.", "A reduced pressure of 0.205 and a reduced temperature of 0.609, taking the ratios the other way up."]'::jsonb, 0, 'Reduced properties are absolute, so the temperature must be in Rankine. The engine uses 459.67 throughout, and when two calculations of the same z differ in the fourth decimal that offset is the first thing to check.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 6, 'Hall-Yarborough gives 0.8577529684232971 and Dranchuk-Abou-Kassem gives 0.8605955632995046 for Ekene at initial pressure. What is that gap?', '["-0.3303055462323185 percent, and it is a fair estimate of how well the z factor is known for this gas.", "-0.3303055462323185 percent, and it is a lower bound on the uncertainty rather than an estimate of it.", "+0.3303055462323185 percent, since Hall-Yarborough is the larger of the two at this reduced state.", "About three percent, which is the published scatter of the Standing-Katz chart the two correlations both fit."]'::jsonb, 1, 'It is a lower bound because both correlations are fitting the SAME chart. Any error in the chart itself, or in the pseudo-criticals that placed this gas on it, is common to both and the comparison cannot see it.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 7, 'Why is running both z correlations worth the trouble?', '["Because averaging the two is more accurate than either alone, which is the standard practice for chart fits.", "Because the two have different validity ranges, so one of them will usually cover conditions the other does not.", "Because it costs one extra function call and it catches an implementation or a reduced-state error immediately.", "Because the difference between them is the quantity the engine''s warning function checks against its bounds."]'::jsonb, 2, 'If two independent correlations agree to a third of a percent, both implementations are probably right. If they disagree by ten percent, you have found out in a second rather than after a history match.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 8, 'What does the gas formation volume factor need that Bo does not?', '["A separate correlation for the gas, fitted in the same way the oil correlations were fitted to their own data.", "A bubble point, since the gas formation volume factor is undefined above the pressure at which free gas exists.", "A gas gravity correction, applied on top of the ideal gas law in the same way the oil gravity enters Bo.", "Nothing beyond a z factor, after which it is arithmetic."]'::jsonb, 3, 'All the uncertainty in Bg is inherited from z, so a third of a percent of disagreement in z is a third of a percent in Bg and nothing else is added.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 9, 'Bg is inverse in pressure and linear in absolute temperature. What does the inverse dependence explain?', '["Why gas expansion is a strong drive mechanism and oil expansion is a weak one.", "Why gas reservoirs deplete at nearly constant pressure until late in life, which is the shape of a gas material balance.", "Why the gas formation volume factor is quoted in reservoir barrels per standard cubic foot rather than the other way round.", "Why a gas cap expands to fill the space vacated by produced oil, which is what makes gas cap drive efficient."]'::jsonb, 0, 'Double the pressure and Bg halves at fixed z. Oil is nearly incompressible, so oil expansion releases very little energy per unit of pressure drop.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 10, 'The engine has two functions named bgRbPerScf. What is the difference?', '["Different units: one returns reservoir barrels per standard cubic foot and the other cubic feet per standard cubic foot.", "Different constants and different argument orders: the black-oil one carries 0.005035 on (p, T, z) and the compositional one the exact standard-conditions form on (z, T, p).", "Different physics: one uses a z factor from a correlation and the other computes it from the compositional flash.", "Nothing substantive; the duplication is a legacy of the extraction and the two are numerically identical."]'::jsonb, 1, 'They differ by a fixed 0.0356 percent. Neither is wrong, importing the wrong one is, and reversing the arguments is worse, which is why the engine pins the difference with a test.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 11, 'A gas viscosity comes out at 0.9 cp. What has happened?', '["Nothing unusual; a heavy gas at high pressure and low temperature can reach that viscosity.", "The oil viscosity has been reported instead, since 0.9 cp is a typical value for a live oil at reservoir conditions.", "A unit or an input error, because a natural gas at reservoir conditions sits between about 0.01 and 0.05 cp.", "The correlation has been run outside its published range, which the engine''s warning function would have flagged."]'::jsonb, 2, 'Gas viscosity is one of the few quantities where the plausible range is narrow enough that the order-of-magnitude check is decisive. The oil-viscosity confusion is possible and it is a different diagnosis.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 12, 'How does temperature affect gas viscosity compared with liquid viscosity?', '["It thickens a gas at fixed density and thins a liquid, because gas viscosity comes from molecules crossing between layers rather than from cohesion.", "It thins both, though the effect is much weaker in a gas because the molecules are already far apart.", "It thickens both, since higher temperature means faster molecules and therefore more resistance to shear.", "It has almost no effect on a gas, which is why gas viscosity is often treated as constant across a reservoir."]'::jsonb, 0, 'That reversal is worth holding onto. It is one of the few places where a gas and a liquid respond to the same variable in opposite directions.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 13, 'Why does formation water belong in a black-oil description even on a field that has never produced water?', '["Because the water saturation enters the relative permeability curves, which the fluid description has to be consistent with.", "Because a simulator refuses a deck without a water formation volume factor, whatever the field actually produces.", "Because the aquifer will eventually encroach, so the properties are needed for the later part of the forecast.", "Because connate water is present everywhere and its expansion contributes to the drive in an undersaturated reservoir."]'::jsonb, 3, 'Above the bubble point, water and rock expansion can be a serious fraction of the drive, because the water volume is large even though its compressibility is small. That is the term people miss.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 14, 'What does salinity do to the two water properties?', '["It raises both appreciably, which is why the engine takes a salinity in parts per million for each of them.", "It raises the viscosity appreciably and its effect on the formation volume factor is small enough that the engine handles it implicitly.", "It lowers the viscosity and raises the formation volume factor, since dissolved salts increase the density.", "It affects neither at reservoir conditions, which is why a pure water baseline is adequate for both."]'::jsonb, 1, 'Brine at 100000 ppm is noticeably more viscous than fresh water at the same temperature. The engine''s McCain viscosity takes a salinity for exactly that reason and its Bw does not.'),
  ('fluid', 'beginner', 'module', 'm05-gas-and-water', 15, 'Why does the engine offer only one water correlation where it offers three for oil?', '["Because water properties are computed by the simulator rather than by the fluid description, so only a default is needed.", "Because McCain''s correlation covers the full range of salinity and temperature, so the alternatives were never published.", "Because water is far more predictable, so there is not the same spread of published correlations, and offering a choice would imply an uncertainty that does not exist.", "Because water enters only through the voidage calculation, where a few percent of error is not material."]'::jsonb, 2, 'That is honest design. The correlation-choice structure makes it explicit: the water field can only be mccain.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Which tier does Ekene''s fluid sit on?', '["Published method, since every one of its four properties can be reproduced by running a published correlation.", "None of the six, because it was designed rather than produced by any of them, and that is its own kind of answer.", "Measured, since the values were fixed by the material balance course and have been treated as data ever since.", "Screening, since no laboratory has ever seen this fluid and the values were chosen rather than determined."]'::jsonb, 1, 'It is a decision, and a decision belongs in the report as a decision. Reproducing a designed value with a correlation is exactly what this tier showed does NOT happen.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Capstone field 1 asks for Standing''s bubble point on Ekene. What is the likely mistake?', '["Using Vasquez-Beggs, which is the engine''s default correlation and gives a different bubble point entirely.", "Applying the undersaturated correction, which is what turns a saturated bubble point into a value at initial pressure.", "Running the correlation the other way, fixing the bubble point at 2000 and reading a solution gas ratio instead.", "Forgetting the temperature, which the correlation needs and which is not stated with the fluid description."]'::jsonb, 2, 'That returns 421.94 scf/stb, which the simulation course grades and which is not what this field asks for. Standing is the engine''s default and the temperature of 180 F is stated everywhere.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Capstone field 2 asks for Standing''s Bo. At which solution gas ratio?', '["The DESIGNED 400 scf/stb, and not the correlated 421.94 scf/stb, which would instead give 1.2516120850485737.", "The correlated 421.94 scf/stb, because a correlated Bo should be evaluated on a correlated solution gas ratio.", "Whichever the panel defaults to, since the field''s tolerance is wide enough to accept either of the two.", "The solution gas ratio at the initial pressure of 3200 psia, which is where a formation volume factor is usually quoted."]'::jsonb, 0, 'The second mistake is applying the undersaturated correction, which would be right at initial pressure and is wrong here, because the field asks for the saturated value at the bubble point.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Capstone field 3 asks for Beal''s dead oil viscosity. What are the two likely mistakes?', '["Reporting it at stock tank temperature rather than reservoir temperature, and using the wrong oil gravity.", "Reporting the undersaturated value at initial pressure, and forgetting that dead oil has no pressure dependence.", "Using the correlated solution gas ratio, and using the designed viscosity of 1.8 cp as an input rather than an output.", "Reporting the live oil viscosity, and using Beggs and Robinson''s own dead oil correlation instead of Beal''s."]'::jsonb, 3, 'The live oil viscosity is roughly a third of the answer, so the error is large once you know to look. Beggs and Robinson published their own dead oil correlation, which is a different published method giving a different number.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Capstone fields 4 and 5 are evaluated at which pressure?', '["2600 psia, which is the pressure at which the undersaturated viscosity is quoted elsewhere in the tier.", "3200 psia, which is Ekene''s initial pressure, and the deck''s own equilibration datum pressure agrees.", "2000 psia, which is the bubble point and the pressure every other capstone field in this tier uses.", "Whichever pressure the learner chooses, since the field states the reduced state rather than the pressure."]'::jsonb, 1, 'Using 2600 psia would return a plausible-looking number for both fields and it is not one of Ekene''s own pressures for these quantities. The tier states 3200 in several places.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 6, 'A learner reports the z gap as a positive 0.33 percent. What have they got wrong?', '["The pressure: the gap has to be evaluated at 3200 psia and they have used the bubble point of 2000 instead.", "The units: they have reported the absolute difference in z rather than the percentage the field asks for.", "The sign: Hall-Yarborough is the SMALLER of the two at this state, so the gap is negative.", "The denominator: they have taken the percentage relative to Hall-Yarborough rather than to Dranchuk-Abou-Kassem."]'::jsonb, 2, 'The other three are all real mistakes available on this field and none of them flips the sign. The field''s tolerance will not forgive a sign error.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 7, 'What is the single most useful check on any correlation output in this tier?', '["The direction: a bubble point that falls when you add gas, or a Bo below one for a live oil, has been computed wrongly.", "The precision: an answer carrying fewer than six significant figures indicates the correlation was run in the wrong mode.", "The validity warning: if none fires, the conditions are inside the range and the answer can be relied on.", "The agreement with the designed value, since Ekene''s designed set is what the correlations are being held against."]'::jsonb, 0, 'Direction checks cost nothing and catch the errors that are otherwise invisible. Absence of a warning means the conditions are inside the range and says nothing about the scatter within it.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What did this tier establish about the relationship between precision and accuracy?', '["Precision should always match accuracy, so a correlated value should be rounded before it is stored anywhere.", "Accuracy improves with precision as long as the inputs carry enough figures, which is why the engine keeps them all.", "Precision is the property the tier grades, since a capstone tolerance is a statement about digits rather than about error.", "Sixteen digits from a correlation fitted to a hundred measurements is arithmetic, not knowledge."]'::jsonb, 3, 'The engine returns full precision because that is what a double holds. Quote 1912 psia to somebody who has to act on it, and carry the rest only where you are checking that two calculations agree.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Which two quantities did this tier find disagree most between the designed and the correlated Ekene fluid?', '["The bubble point and the solution gas ratio, since both are the same disagreement expressed twice.", "The viscosity, by a factor of 2.4, against a few percent on the volume properties.", "The z factor and the gas formation volume factor, since the second inherits everything wrong with the first.", "The formation volume factor and the water properties, since neither was ever anchored to a measurement."]'::jsonb, 1, 'That asymmetry is typical: volume behaviour correlates well from gravity and temperature and viscosity depends on molecular detail that neither captures. It is the argument for measuring viscosity first.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 10, 'What does a chain mean for how a number should be reported?', '["The number and its validity warnings, since the warnings name the correlations and therefore imply the chain.", "The number and the tier, since the tier already encodes what kind of evidence stands behind it.", "The number, the correlations in order, and the inputs each consumed, so that somebody else can reproduce it.", "The number rounded to the precision the weakest link supports, which makes the chain visible without naming it."]'::jsonb, 2, 'A bare number is not reproducible. The warnings, the tier and the rounding are all good practice and none of them says which chain ran.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Why did the simulation deck carry the designed fluid rather than a correlated one?', '["Because the tank model, the flood ledger and the displacement curves were all built on it, and changing it makes them silently inconsistent.", "Because the designed values are closer to the truth, having been chosen by an engineer who knew the field.", "Because a deck cannot express a correlation, so a table of designed values is the only form a simulator accepts.", "Because the correlated values fall outside Standing''s validity range at Ekene''s gravity and temperature."]'::jsonb, 0, 'Nothing errors when a fluid is swapped. The numbers just quietly stop meaning what the documents say they mean, which is why the rule is that a deck''s fluid must be the fluid the study was matched against.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What are the three things this tier did NOT do?', '["It ran no equation of state, it tuned nothing, and it never left the black-oil description.", "It ignored water, it ignored gas condensates, and it never considered a fluid outside its validity range.", "It computed no gas properties, it quoted no viscosity, and it never crossed the bubble point.", "It measured nothing, it used no composition, and it checked no correlation against a real fluid."]'::jsonb, 3, 'Three correlations disagreeing tells you that they disagree. It cannot tell you which is closer, because there was nothing to be closer to, and that is what the Professional tier supplies.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What does the Professional tier add?', '["A tuned equation of state, which is the strongest description available once measurements exist.", "A real published study, Core Laboratories RFL 88001, with measurements to hold a model up against.", "A compositional description of Ekene, so that the designed fluid can finally be run through an equation of state.", "A second designed fluid at different conditions, so the correlations can be tested over a wider range."]'::jsonb, 1, 'It contains what a laboratory actually does: a constant composition expansion, a differential liberation, separator tests and a composition to a C7+ fraction. Tuning is the Expert tier.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 14, 'What is the habit this tier is trying to build?', '["Run every available correlation and report the spread rather than any single value.", "Round every correlated number to two significant figures before it enters any downstream calculation.", "Ask what tier a number is on before asking whether it is right.", "Prefer measured values wherever they exist and correlated values only where they do not."]'::jsonb, 2, 'A screening number that happens to be right is still a screening number, and quoting it as though it were measured misleads the next reader whatever its value. The other three are good practice and narrower.'),
  ('fluid', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What is the misconception about correlations and equations of state?', '["That correlations are for screening and real work uses an equation of state, when an untuned equation of state can be further from the truth.", "That an equation of state needs a composition, when a black-oil description is sufficient input for most of them.", "That correlations are older, when several of the standard set were published after the cubic equations of state.", "That the two answer the same question, when a correlation gives a property and an equation of state gives a phase split."]'::jsonb, 0, 'Real work uses whichever is better constrained for the question, and the Professional tier measures an untuned equation of state doing worse than a separator test on a stock tank gravity. The evidence behind a number is the point, not the machinery.'),
  ('fluid', 'beginner', 'final', null, 1, 'Name the four black-oil properties.', '["Oil gravity, gas gravity, reservoir temperature and pressure, which every correlation takes as inputs.", "Solution gas ratio, formation volume factor, oil viscosity and the bubble point pressure.", "Porosity, permeability, saturation and net pay, which the volumetric estimate combines.", "Density, compressibility, thermal expansion and molecular weight, the thermodynamic state properties."]'::jsonb, 1, 'A gas description adds z, Bg and gas viscosity; a water description adds Bw and water viscosity. The first distractor lists the correlations'' INPUTS rather than their outputs.'),
  ('fluid', 'beginner', 'final', null, 2, 'Why does an error in the formation volume factor not average away across a field?', '["Because it is systematic rather than random, so it compounds in the same direction through every calculation that uses it.", "Because it enters multiplicatively, and multiplicative errors always grow rather than cancel.", "Because different parts of the reservoir sit at different pressures, so the errors are uncorrelated.", "Because it appears in both the numerator and the denominator, so the two contributions reinforce."]'::jsonb, 0, 'A Bo that is three percent high is three percent high in the oil in place, the voidage, the recovery factor''s denominator and the forecast.'),
  ('fluid', 'beginner', 'final', null, 3, 'How many kinds of origin can a number in a fluid description have?', '["Two: measured or computed, with everything else a variant of one of those.", "Three: measured, correlated or assumed, which are the three a report has to distinguish between.", "It varies by quantity, since a bubble point can be measured and a viscosity chain cannot.", "Four: measured, correlated, computed by a tuned equation of state, or estimated by an unchecked method."]'::jsonb, 3, 'All four are legitimate in the right place. Presenting the fourth as though it were the first is not, and that distinction is what the whole course is built on.'),
  ('fluid', 'beginner', 'final', null, 4, 'What are the six tiers on the engine''s provenance ladder?', '["Certain, likely, plausible, screening, speculative and placeholder, ranked by confidence in the value.", "Laboratory, field, literature, correlation, simulation and default, ranked by where the value originated.", "Measured, armed, oracle gated, lab tuned, published method and screening.", "Measured, correlated, computed, estimated, assumed and unknown, which are the six a report distinguishes."]'::jsonb, 2, 'Armed means the engine reproduces a published study within a stated tolerance. Oracle gated means an independent implementation agrees on the arithmetic and says nothing about the physics suiting the fluid.'),
  ('fluid', 'beginner', 'final', null, 5, 'What does a tier tell you?', '["What kind of confidence you have rather than how much, so reading it means asking what the tier is confidence about.", "How large the error is likely to be, on a scale calibrated against the engine''s gate suite.", "Whether the number may be used in a reserves booking, which is what the ladder was designed to decide.", "How much a number would cost to improve, which is what makes the ladder useful for planning."]'::jsonb, 0, 'An oracle gated flash is arithmetically exact and can still describe the wrong fluid. A published method correlation has no independent check and may be fine for a screening study.'),
  ('fluid', 'beginner', 'final', null, 6, 'Which tier does this course refuse to grade?', '["Lab tuned, because a tuned value depends entirely on which measurements it was tuned to and is not reproducible.", "Screening, because certifying that a learner can produce a number implies the number is worth producing.", "Published method, because a method with no independent check cannot support a graded field.", "Measured, because the course has no laboratory and cannot ask a learner to reproduce an experiment."]'::jsonb, 1, 'The Expert tier has a whole module on screening quantities and grades none of it. Teaching a number and certifying it are different acts.'),
  ('fluid', 'beginner', 'final', null, 7, 'What does the black-oil model replace a reservoir fluid with?', '["One component, since a black oil is a single liquid phase over the pressure range of interest.", "Three components, an oil, a gas and a water, each with its own formation volume factor.", "Eleven components, being the nine identifiable light ones plus a heavy fraction and an inert.", "Two pseudo-components, a stock tank oil and a surface gas."]'::jsonb, 3, 'It works because for most oil reservoirs the composition does not change much. Water is present and is not one of the two the model is named for.'),
  ('fluid', 'beginner', 'final', null, 8, 'Define a bubble point pressure.', '["The pressure at which a well first begins to produce free gas, as read off the producing gas-oil ratio history over time.", "The pressure at which the oil and the gas phases reach equal density and become indistinguishable inside the cell.", "The pressure at which the first bubble of gas appears as an oil is expanded at constant reservoir temperature.", "The pressure at which the reservoir''s average pressure crosses the saturation pressure of the fluid in place."]'::jsonb, 2, 'It is a property of the fluid at a temperature and nothing else. Free gas does not flow until it exceeds its critical saturation, so the well observation lags the reservoir crossing.'),
  ('fluid', 'beginner', 'final', null, 9, 'What three things happen below the bubble point?', '["The oil shrinks, the oil thickens, and a second and far more mobile phase appears in the pore space.", "The oil expands, the oil thins, and the expansion becomes the field''s principal drive mechanism.", "The oil shrinks, the oil thins, and the freed gas dissolves into the connate water.", "Nothing changes in the oil; only the free gas saturation rises, which makes the crossing hard to detect."]'::jsonb, 0, 'Bo falls because the swelling gas has left, viscosity rises because the thinning gas has left, and gas viscosity is two orders of magnitude below oil viscosity so gas flows preferentially.'),
  ('fluid', 'beginner', 'final', null, 10, 'What was Standing''s correlation fitted to?', '["Over 6000 measurements from a worldwide data set, split into two coefficient sets at 30 API.", "105 bubble points from 22 crude oil and natural gas mixtures, all Californian.", "The Standing-Katz chart, itself assembled from measurements on natural gases in the 1940s.", "A set of North Sea oils, which is why the engine labels it screening rather than published method."]'::jsonb, 1, 'That is the definition rather than a criticism, and it is why three correlations disagree. The others describe Vasquez-Beggs, the z chart and Glaso.'),
  ('fluid', 'beginner', 'final', null, 11, 'Standing gives Ekene 1912.1923059028293 psia against a designed 2000. What is that?', '["About 4.4 percent low, which exceeds the correlation''s own stated accuracy and therefore indicates an input error.", "About 8.8 percent low, since the 88 psia difference should have been taken against the correlated value.", "Exactly the gap the designed fluid was chosen to have, so the course would have something to measure.", "About 4.4 percent low, which is an entirely ordinary distance for a published correlation to sit from any particular oil."]'::jsonb, 3, 'The designed 2000 is a decision and the correlated 1912 is what a fit to Californian oils says. Neither is a measurement of Ekene, because nobody has measured Ekene.'),
  ('fluid', 'beginner', 'final', null, 12, 'Why should three disagreeing correlations not be averaged?', '["Because the average of three fits to three different populations is a fit to nothing, with no error bar and no provenance.", "Because averaging weights the screening correlation equally with the two published-method ones.", "Because the three are not independent, all three having been fitted partly to the same underlying measurements.", "Because the average would fall outside the validity range of at least one of the three correlations."]'::jsonb, 0, 'The spread is the useful output: it measures how well a correlation can know this fluid. Averaging hides the disagreement instead of reporting it.'),
  ('fluid', 'beginner', 'final', null, 13, 'A single mistyped exponent leaves both directions looking plausible. What catches it?', '["Continuity at the bubble point, so the saturated and undersaturated branches meet without a step.", "Agreement with a second correlation to within the published scatter of the two data sets.", "The round trip: Rs in gives Pb out, and feeding that Pb back in must return the original Rs.", "Monotonicity in pressure, so a root-finder solving either direction cannot land on the wrong solution."]'::jsonb, 2, 'A single mistyped exponent breaks the round trip while leaving each direction looking plausible. The engine gates it for all three correlations.'),
  ('fluid', 'beginner', 'final', null, 14, 'Why do all three Rs correlations take a bubble point as well as a pressure?', '["Because the bubble point selects which coefficient set applies, as Vasquez-Beggs splits at 30 API.", "Because an undersaturated oil has released no gas, so Rs above the bubble point is constant at Rsb.", "Because the correlations were fitted on data reporting both, so dropping either leaves the fit under-determined.", "Because the bubble point sets the validity range the warning function checks the pressure against."]'::jsonb, 1, 'A correlation that kept increasing Rs above the bubble point would be describing an oil that dissolves gas which is not there.'),
  ('fluid', 'beginner', 'final', null, 15, 'Both volumes in a solution gas ratio are measured where?', '["A reservoir gas volume over a reservoir oil volume, at the pressure and temperature of interest.", "A surface gas volume over a reservoir oil volume, which is why Bo is needed to convert it.", "A mass of dissolved gas over a mass of oil, converted into volumes at the end using the two standard densities.", "At surface: gas at standard conditions over oil in a stock tank, for a fluid that is in the reservoir."]'::jsonb, 3, 'Both volumes are countable at surface with ordinary equipment. A reservoir-condition definition would not correspond to anything anybody sells.'),
  ('fluid', 'beginner', 'final', null, 16, 'A well reports a gas-oil ratio three times the solution gas ratio. What does that say?', '["That free gas is flowing, so the reservoir is below its bubble point and the producing ratio has climbed away from Rs.", "The first is measured at the separator and the second at the wellhead, so they differ by tubing losses.", "The first excludes gas cap gas and the second includes it, so they differ by the cap''s contribution.", "They are the same quantity, one name used in reservoir engineering and the other in production."]'::jsonb, 0, 'Below the bubble point free gas flows preferentially, so the producing ratio climbs above Rs and keeps climbing. The gap is the diagnostic.'),
  ('fluid', 'beginner', 'final', null, 17, 'Why is Bo above one for a live oil?', '["Because reservoir temperature exceeds 60 F, and thermal expansion on its own accounts for the whole excess.", "Because the reference volume is defined at a lower pressure, so the ratio exceeds one by construction.", "Because dissolved gas swells the oil, and that beats the compression pressure applies.", "Because the correlations were fitted with a lower bound of one, so a smaller value is out of range."]'::jsonb, 2, 'Swelling and thermal expansion push it up, compression pushes it back, and swelling wins comfortably. A dead oil would sit just above one from temperature alone.'),
  ('fluid', 'beginner', 'final', null, 18, 'Where does Bo peak?', '["At atmospheric pressure, where the oil has released all its gas and occupies the least reservoir space.", "At the bubble point, because below it gas is leaving and above it the oil is being compressed.", "At the initial pressure, since that is the highest pressure the reservoir fluid has experienced.", "It does not peak; Bo rises monotonically with pressure across the whole range."]'::jsonb, 1, 'That peak is the most distinctive feature of a black-oil table and the fastest way to spot one assembled wrongly.'),
  ('fluid', 'beginner', 'final', null, 19, 'Standing gives Ekene 1.2407824121407645 rb/stb at the designed 400 scf/stb. What does the gap do?', '["About 3.4 percent, which becomes a 3.4 percent error in every volume the field ever books.", "About 3.4 percent, which cancels against the voidage calculation because Bo appears in both.", "About 34 percent, taking the ratio of the correlated value to the designed 1.2 directly.", "Nothing measurable, since it is well inside the uncertainty of the porosity and saturation inputs."]'::jsonb, 0, 'On Ekene''s booked 12.139 million barrels that is roughly 400 thousand barrels, and it is sixty times the residual the simulation course closed on its structure.'),
  ('fluid', 'beginner', 'final', null, 20, 'A field is managed at a voidage replacement ratio of 1.03. Bo turns out 3.4 percent larger. What now?', '["Raises it by about the same amount, because more reservoir volume was produced for the same injected volume.", "Leaves it unchanged, because both the injected and the produced sides scale with the same factor.", "Changes it unpredictably, because Bo enters the produced side and Bw the injected side.", "It is really about 1.00, because produced voidage multiplies by Bo and sits in the denominator of the ratio."]'::jsonb, 3, 'A field managed at 1.03 would be reported at about 1.00, which is the difference between replacing voidage and not.'),
  ('fluid', 'beginner', 'final', null, 21, 'Who applies the undersaturated correction to a formation volume factor?', '["The correlations clamp internally at the bubble point, exactly as the Rs correlations do.", "The correlations extrapolate their fitted form, which is why a validity warning fires above the bubble point.", "The caller does, through a compressibility; the correlations themselves return only the saturated value.", "The engine interpolates between the bubble point value and unity at the initial pressure."]'::jsonb, 2, 'Asking a Bo correlation for the value at 3200 psia on an oil that bubbles at 2000, and expecting it to handle the undersaturation, gets you the bubble point value.'),
  ('fluid', 'beginner', 'final', null, 22, 'An engineer measures a stock tank sample at ambient temperature and calls it the dead oil viscosity. What is wrong?', '["Oil with no dissolved gas at stock tank conditions, which is what a tank sample actually is.", "The temperature: a dead oil viscosity is defined at RESERVOIR temperature, and a tank sample is not at it.", "Oil from a reservoir depleted below its abandonment pressure, which no longer flows to the wells.", "Oil whose light components were lost during sampling, so its properties understate the live fluid."]'::jsonb, 1, 'Measuring a tank sample at ambient temperature and using it as the dead oil viscosity gives a number far too high, and the error propagates through the whole chain.'),
  ('fluid', 'beginner', 'final', null, 23, 'Beal raises API gravity to the power 4.53 in a denominator. What follows?', '["Viscosity falls extremely steeply with gravity, so a 20 API and a 40 API oil differ by more than an order of magnitude.", "Viscosity is largely insensitive to gravity, since a large exponent compresses the range of outcomes.", "The correlation cannot be used below 20 API, because the denominator grows without bound there.", "Gravity must be known to four figures, because the exponent amplifies rounding in the input."]'::jsonb, 0, 'It also makes viscosity correlations far more sensitive to a gravity error than volume correlations are.'),
  ('fluid', 'beginner', 'final', null, 24, 'Beal gives Ekene 2.3437444714709295 cp against a designed live oil viscosity of 1.8 cp. Is that the right way round?', '["No: a dead oil should be thinner, having lost the heavy components that make a live oil viscous.", "Yes, but only because the two are quoted at different temperatures and would agree at a common one.", "It cannot be judged, since dead and live oil viscosities are not comparable quantities.", "Yes: the dead oil is thicker because the gas that thins it has not been put back into it."]'::jsonb, 3, 'Dissolved gas thins oil substantially and putting it back is the next step of the chain. The two are directly comparable and the ordering is the check.'),
  ('fluid', 'beginner', 'final', null, 25, 'Beggs and Robinson take Ekene''s dead oil to 0.7559673199800581 cp. What is the size of that effect?', '["The oil has been thinned by about a third, a modest correction compared with what pressure does.", "The oil has been thickened, since dissolved gas increases the density and therefore the resistance to flow.", "The oil has been thinned to less than a third of its dead value.", "The effect cannot be separated from the temperature dependence, since both enter the same exponential."]'::jsonb, 2, 'That is why a viscosity quoted without saying whether it is live or dead means very little. Pressure above the bubble point moves it by a few percent, not a factor of three.'),
  ('fluid', 'beginner', 'final', null, 26, 'The chain gives 0.7559673199800581 cp at 400 scf/stb and 0.7341185203712621 cp at 421.94. Which is correct?', '["The second, since 421.94 is what Standing returns at the designed bubble point.", "Both, and quoting either without saying which solution gas ratio went in is what is wrong.", "The first, since the designed 400 is what the rest of the series carries and consistency governs.", "Neither, since mixing a designed solution gas ratio with a correlated viscosity chain is indefensible."]'::jsonb, 1, 'Same correlations, same fluid, different answer, because the input differed. The number plus the chain that produced it is the answer.'),
  ('fluid', 'beginner', 'final', null, 27, 'What shape does the oil viscosity curve have?', '["A minimum at the bubble point, rising as pressure falls below it and rising as pressure rises above it.", "A maximum at the bubble point, mirroring the shape of the formation volume factor.", "A monotonic fall with pressure, since expansion and gas release both thin the oil.", "A step at the bubble point, since the mechanism changes discontinuously there."]'::jsonb, 0, 'Below the bubble point gas is leaving; above it the oil is being compressed. The two mechanisms compete and change places at the bubble point.'),
  ('fluid', 'beginner', 'final', null, 28, 'What does composing three viscosity correlations do to the uncertainty?', '["The errors partly cancel, since the three were fitted to different data sets with independent biases.", "The uncertainty is set by the last stage, where the final number is produced and rounded.", "The errors compound rather than average, and the first stage usually contributes the most.", "The uncertainty becomes unquantifiable, since no published scatter exists for a composed chain."]'::jsonb, 2, 'Beal''s dead oil scatter is the widest of the three, so an undersaturated viscosity that looks precise inherits a dead oil viscosity that was never precise.'),
  ('fluid', 'beginner', 'final', null, 29, 'The ideal gas law does not hold for a natural gas at reservoir conditions. What is z?', '["The compressibility of the gas, being the fractional volume change per unit pressure change.", "The ratio of the gas density at reservoir conditions to its density at standard conditions.", "A correction for the gas gravity, since a heavier gas departs further from ideality at the same reduced state.", "Exactly the factor that makes it true, so it is the ratio of the real molar volume to the ideal one."]'::jsonb, 3, 'It is a fudge factor with a precise meaning: the ratio of the real molar volume to the ideal one. The others are different quantities.'),
  ('fluid', 'beginner', 'final', null, 30, 'Why does one z chart serve all natural gases?', '["Because natural gases are all mostly methane, so one component dominates the behaviour in every case.", "Corresponding states: two gases at the same reduced pressure and temperature behave alike.", "Because the chart is drawn for a reference gas with a gravity correction applied afterward.", "Because the departures from ideality are small enough that one average curve is adequate."]'::jsonb, 1, 'The pseudo-criticals are a mixture average, and for a gas of known gravity the engine uses Sutton (1985) to obtain them.'),
  ('fluid', 'beginner', 'final', null, 31, 'For a 0.75 gas at 3200 psia and 180 F, what is the reduced state?', '["A reduced pressure of 4.874147976086212 and a reduced temperature of 1.6414421349756225 in Rankine.", "A reduced pressure of 4.874147976086212 and a reduced temperature of 0.4618, taking temperature in Fahrenheit.", "A reduced pressure of 4.234 and a reduced temperature of 1.6414421349756225, using 460 not 459.67.", "A reduced pressure of 0.205 and a reduced temperature of 0.609, taking both ratios the other way up."]'::jsonb, 0, 'Reduced properties are absolute, so temperature must be in Rankine. The engine uses 459.67 throughout, and that offset is the first thing to check when two calculations differ in the fourth decimal.'),
  ('fluid', 'beginner', 'final', null, 32, 'The two z correlations differ by -0.3303055462323185 percent on Ekene. What is that number?', '["A fair estimate of how well the z factor is known for this gas at this state.", "The published scatter of the Standing-Katz chart, which both correlations reproduce to within it.", "A lower bound on the uncertainty rather than an estimate of it, because both fit the same chart.", "An implementation discrepancy, since two correct fits to one chart should agree to machine precision."]'::jsonb, 2, 'Any error in the chart itself, or in the pseudo-criticals that placed this gas on it, is common to both and the comparison cannot see it.'),
  ('fluid', 'beginner', 'final', null, 33, 'What does Bg need beyond a z factor?', '["A separate correlation fitted to gas volumetric data in the way the oil correlations were fitted.", "Nothing; after z it is arithmetic.", "A gas gravity correction applied on top of the ideal gas law, as oil gravity enters Bo.", "A bubble point, since Bg is undefined above the pressure at which free gas can exist."]'::jsonb, 1, 'All the uncertainty in Bg is inherited from z, so a third of a percent of disagreement in z is a third of a percent in Bg and nothing else is added.'),
  ('fluid', 'beginner', 'final', null, 34, 'The engine has two functions named bgRbPerScf. What differs?', '["The units, one returning reservoir barrels per standard cubic foot and the other cubic feet per cubic foot.", "The physics, one using a correlated z and the other a z from the compositional flash.", "Nothing substantive; the duplication is a legacy of the extraction and the two agree exactly.", "The constant and the argument order."]'::jsonb, 3, 'The black-oil one carries 0.005035 on (p, T, z) and the compositional one the exact standard-conditions form on (z, T, p). They differ by a fixed 0.0356 percent and the engine pins that gap with a test.'),
  ('fluid', 'beginner', 'final', null, 35, 'Why does formation water matter on a field that has never produced water?', '["Because connate water is present everywhere and its expansion contributes to the drive in an undersaturated reservoir.", "Because a simulator refuses a deck without a water formation volume factor, whatever the field produces.", "Because the water saturation enters the relative permeability curves the description must be consistent with.", "Because an aquifer will eventually encroach, so the properties are needed for the later forecast."]'::jsonb, 0, 'Above the bubble point, water and rock expansion can be a serious fraction of the drive, because the water volume is large even though its compressibility is small.'),
  ('fluid', 'beginner', 'final', null, 36, 'A reader asks which provenance tier Ekene''s four fluid properties sit on. What is the answer?', '["Published method, since all four properties can be reproduced by running a published correlation.", "Measured, since the values were fixed early and have been treated as data by every course since.", "None of the six, because the four values were designed rather than produced by any of those routes.", "Screening, since no laboratory has seen this fluid and the values were chosen rather than determined."]'::jsonb, 2, 'It is a decision, and a decision belongs in the report as one. Reproducing a designed value with a correlation is exactly what this tier showed does not happen.'),
  ('fluid', 'beginner', 'final', null, 37, 'At which pressure are the capstone''s gas fields evaluated?', '["3200 psia, Ekene''s initial pressure, which the deck''s own equilibration datum pressure agrees with.", "2600 psia, which is where the undersaturated viscosity is quoted elsewhere in the tier.", "2000 psia, the bubble point, which the other capstone fields in this tier use.", "Whichever the learner chooses, since the field states a reduced state rather than a pressure."]'::jsonb, 0, 'Using 2600 psia returns a plausible-looking number and it is not one of Ekene''s own pressures for these quantities.'),
  ('fluid', 'beginner', 'final', null, 38, 'What is the single most useful check on a correlation output?', '["The validity warning, since no warning means the conditions are inside the fitted range.", "The direction: a bubble point that falls when more gas is added has been computed wrongly.", "The precision, since fewer than six significant figures indicates the correlation ran in the wrong mode.", "The agreement with the designed value, which is what the correlations are being held against."]'::jsonb, 1, 'Direction checks cost nothing and catch errors that are otherwise invisible. Absence of a warning says the conditions are inside the range and nothing about the scatter within it.'),
  ('fluid', 'beginner', 'final', null, 39, 'What is the relationship between precision and accuracy here?', '["Precision should always match accuracy, so a correlated value ought to be rounded before it is stored anywhere.", "Accuracy improves with precision as long as the inputs carry enough figures.", "Precision is what a capstone tolerance measures, so it is the property the course grades.", "Sixteen digits from a correlation fitted to a hundred measurements is arithmetic, not knowledge."]'::jsonb, 3, 'The engine returns full precision because that is what a double holds. Quote 1912 psia to somebody who must act on it, and carry the rest only where you are checking two calculations agree.'),
  ('fluid', 'beginner', 'final', null, 40, 'Which quantity disagrees most between the designed and correlated Ekene fluid?', '["The bubble point, since the same disagreement expressed as a pressure is the largest in absolute terms.", "The gas formation volume factor, since it inherits everything wrong with the z factor above it.", "The oil viscosity, by a factor of 2.4, against just a few percent on the volumetric properties.", "The water properties, since neither was ever anchored to a measurement or a design decision."]'::jsonb, 2, 'Volume behaviour correlates well from gravity and temperature and viscosity depends on molecular detail neither captures. That is the argument for measuring viscosity first.'),
  ('fluid', 'beginner', 'final', null, 41, 'Why does the simulation deck carry the designed fluid?', '["Because the tank model, the flood ledger and the displacement curves were all built on it, and changing it makes them silently inconsistent.", "Because the designed values are closer to the truth, chosen by an engineer who knew the field.", "Because a deck cannot express a correlation, so a table of designed values is the only accepted form.", "Because the correlated values fall outside Standing''s validity range at Ekene''s gravity and temperature."]'::jsonb, 0, 'Nothing errors when a fluid is swapped. The numbers just stop meaning what the documents say they mean.'),
  ('fluid', 'beginner', 'final', null, 42, 'What is the habit this tier builds?', '["Round every correlated number to two significant figures before it enters a downstream calculation.", "Ask what tier a number is on before asking whether it is right.", "Run every available correlation and report the spread rather than any single value.", "Prefer measured values wherever they exist and correlated values only where they do not."]'::jsonb, 1, 'A screening number that happens to be right is still a screening number, and quoting it as measured misleads the next reader whatever its value. The others are good practice and narrower.');
